namespace sv_17f33b4a1fd64ad888458361b5d9aa7e.Client.Services;

public interface IShipmentService
{
    Task<ShipmentDetails> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

public sealed class ShipmentDetails
{
    public required string TrackingNumber { get; init; }
    public required string Status { get; init; }
    public required string Location { get; init; }
    public required DateTimeOffset EstimatedDelivery { get; init; }
    public required IReadOnlyList<StatusUpdate> StatusUpdates { get; init; }
}

public sealed class StatusUpdate
{
    public required DateTimeOffset Timestamp { get; init; }
    public required string Description { get; init; }
    public required string Location { get; init; }
}

using sv_17f33b4a1fd64ad888458361b5d9aa7e.Client.Services;

namespace sv_17f33b4a1fd64ad888458361b5d9aa7e.Services;

public sealed class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, ShipmentDetails> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-001"] = new ShipmentDetails
        {
            TrackingNumber = "TRK-001",
            Status = "In Transit",
            Location = "Chicago, IL",
            EstimatedDelivery = new DateTimeOffset(2026, 7, 12, 17, 0, 0, TimeSpan.FromHours(-5)),
            StatusUpdates = new List<StatusUpdate>
            {
                new() { Timestamp = new DateTimeOffset(2026, 7, 5, 9, 0, 0, TimeSpan.FromHours(-5)), Description = "Package picked up", Location = "New York, NY" },
                new() { Timestamp = new DateTimeOffset(2026, 7, 6, 14, 30, 0, TimeSpan.FromHours(-5)), Description = "Departed facility", Location = "New York, NY" },
                new() { Timestamp = new DateTimeOffset(2026, 7, 7, 8, 15, 0, TimeSpan.FromHours(-5)), Description = "Arrived at sorting center", Location = "Chicago, IL" },
            }
        },
        ["TRK-002"] = new ShipmentDetails
        {
            TrackingNumber = "TRK-002",
            Status = "Delivered",
            Location = "San Francisco, CA",
            EstimatedDelivery = new DateTimeOffset(2026, 7, 7, 12, 0, 0, TimeSpan.FromHours(-7)),
            StatusUpdates = new List<StatusUpdate>
            {
                new() { Timestamp = new DateTimeOffset(2026, 7, 3, 10, 0, 0, TimeSpan.FromHours(-7)), Description = "Package picked up", Location = "Los Angeles, CA" },
                new() { Timestamp = new DateTimeOffset(2026, 7, 4, 6, 0, 0, TimeSpan.FromHours(-7)), Description = "In transit", Location = "Bakersfield, CA" },
                new() { Timestamp = new DateTimeOffset(2026, 7, 5, 11, 0, 0, TimeSpan.FromHours(-7)), Description = "Out for delivery", Location = "San Francisco, CA" },
                new() { Timestamp = new DateTimeOffset(2026, 7, 5, 14, 22, 0, TimeSpan.FromHours(-7)), Description = "Delivered", Location = "San Francisco, CA" },
            }
        },
        ["TRK-003"] = new ShipmentDetails
        {
            TrackingNumber = "TRK-003",
            Status = "Processing",
            Location = "Seattle, WA",
            EstimatedDelivery = new DateTimeOffset(2026, 7, 15, 18, 0, 0, TimeSpan.FromHours(-7)),
            StatusUpdates = new List<StatusUpdate>
            {
                new() { Timestamp = new DateTimeOffset(2026, 7, 7, 16, 45, 0, TimeSpan.FromHours(-7)), Description = "Label created", Location = "Seattle, WA" },
            }
        },
    };

    public async Task<ShipmentDetails> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        if (SeedData.TryGetValue(trackingNumber, out var shipment))
        {
            return shipment;
        }

        throw new KeyNotFoundException($"Shipment with tracking number '{trackingNumber}' was not found.");
    }
}

using Microsoft.AspNetCore.Mvc;
using sv_17f33b4a1fd64ad888458361b5d9aa7e.Client.Services;

namespace sv_17f33b4a1fd64ad888458361b5d9aa7e.Controllers;

[ApiController]
[Route("api/shipments")]
public sealed class ShipmentController : ControllerBase
{
    private readonly IShipmentService _shipmentService;

    public ShipmentController(IShipmentService shipmentService)
    {
        _shipmentService = shipmentService;
    }

    [HttpGet("{trackingNumber}")]
    public async Task<IActionResult> GetShipment(string trackingNumber, CancellationToken ct)
    {
        try
        {
            var shipment = await _shipmentService.GetShipmentAsync(trackingNumber, ct);
            return Ok(shipment);
        }
        catch (KeyNotFoundException)
        {
            return NotFound();
        }
    }
}

using System.Net;
using System.Net.Http.Json;

namespace sv_17f33b4a1fd64ad888458361b5d9aa7e.Client.Services;

/// <summary>
/// HTTP-based implementation used when running on WebAssembly.
/// Calls back to the server API to retrieve shipment data.
/// </summary>
public sealed class ShipmentServiceClient : IShipmentService
{
    private readonly HttpClient _httpClient;

    public ShipmentServiceClient(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public async Task<ShipmentDetails> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await _httpClient.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == HttpStatusCode.NotFound)
        {
            throw new KeyNotFoundException($"Shipment with tracking number '{trackingNumber}' was not found.");
        }

        response.EnsureSuccessStatusCode();

        var shipment = await response.Content.ReadFromJsonAsync<ShipmentDetails>(ct)
            ?? throw new InvalidOperationException("Received null response from shipment API.");

        return shipment;
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_17f33b4a1fd64ad888458361b5d9aa7e.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

<h2>Shipment Tracking</h2>

@if (_loading)
{
    <div class="loading-placeholder" aria-busy="true">
        <p>Loading shipment details for <strong>@TrackingNumber</strong>...</p>
    </div>
}
else if (_errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@_errorMessage</p>
        <button class="btn btn-outline-danger" @onclick="RetryLoad">Retry</button>
    </div>
}
else if (_shipment is not null)
{
    <div class="shipment-details">
        <dl>
            <dt>Tracking Number</dt>
            <dd>@_shipment.TrackingNumber</dd>

            <dt>Status</dt>
            <dd>@_shipment.Status</dd>

            <dt>Current Location</dt>
            <dd>@_shipment.Location</dd>

            <dt>Estimated Delivery</dt>
            <dd>@_shipment.EstimatedDelivery.ToString("f")</dd>
        </dl>

        <h3>Status History</h3>
        @if (_shipment.StatusUpdates.Count == 0)
        {
            <p>No status updates yet.</p>
        }
        else
        {
            <table class="table">
                <thead>
                    <tr>
                        <th>Timestamp</th>
                        <th>Description</th>
                        <th>Location</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var update in _shipment.StatusUpdates)
                    {
                        <tr>
                            <td>@update.Timestamp.ToString("g")</td>
                            <td>@update.Description</td>
                            <td>@update.Location</td>
                        </tr>
                    }
                </tbody>
            </table>
        }
    </div>
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = default!;

    private ShipmentDetails? _shipment;
    private bool _loading;
    private string? _errorMessage;
    private CancellationTokenSource? _cts;

    protected override Task OnParametersSetAsync()
    {
        // Cancel any in-flight request when the tracking number changes
        CancelPendingRequest();
        return LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        _loading = true;
        _errorMessage = null;
        _shipment = null;

        _cts = new CancellationTokenSource();
        var ct = _cts.Token;

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Navigation away or disposal — silently stop
            return;
        }
        catch (TaskCanceledException ex) when (ex.InnerException is TimeoutException || !ct.IsCancellationRequested)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please check your connection and try again.";
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please check your connection and try again.";
        }
        catch (KeyNotFoundException ex)
        {
            Logger.LogWarning(ex, "Shipment not found: {TrackingNumber}", TrackingNumber);
            _errorMessage = $"Shipment '{TrackingNumber}' was not found.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong while loading the shipment. Please try again.";
        }
        finally
        {
            _loading = false;
        }
    }

    private Task RetryLoad() => LoadShipmentAsync();

    private void CancelPendingRequest()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }

    public void Dispose()
    {
        CancelPendingRequest();
    }
}

